1	// lifecycle.go implements the generic lifecycle event dispatcher.
2	// It routes normalized events from any agent to the appropriate framework actions.
3	//
4	// The dispatcher inverts the current flow from "agent handler calls framework functions"
5	// to "framework dispatcher calls agent methods." Agents are passive data providers;
6	// the dispatcher handles all orchestration: state transitions, strategy calls,
7	// file change detection, metadata generation.
8	package cli
9	
10	import (
11		"context"
12		"errors"
13		"fmt"
14		"log/slog"
15		"os"
16		"path/filepath"
17		"slices"
18		"strings"
19		"time"
20	
21		"github.com/entireio/cli/cmd/entire/cli/agent"
22		"github.com/entireio/cli/cmd/entire/cli/agent/codex"
23		"github.com/entireio/cli/cmd/entire/cli/agent/types"
24		"github.com/entireio/cli/cmd/entire/cli/logging"
25		"github.com/entireio/cli/cmd/entire/cli/paths"
26		"github.com/entireio/cli/cmd/entire/cli/provenance"
27		"github.com/entireio/cli/cmd/entire/cli/review"
28		"github.com/entireio/cli/cmd/entire/cli/session"
29		"github.com/entireio/cli/cmd/entire/cli/strategy"
30		"github.com/entireio/cli/cmd/entire/cli/transcript"
31		"github.com/entireio/cli/cmd/entire/cli/validation"
32		"github.com/entireio/cli/perf"
33	)
34	
35	// eventBypassesAgentOwnershipCheck reports whether an event must run
36	// regardless of the recorded session-owning agent:
37	//   - SessionStart fires before SessionState exists; the hint file dedup
38	//     in handleLifecycleSessionStart already prevents a duplicate banner.
39	//   - TurnStart needs to reach InitializeSession so transcript-path
40	//     resolution can repair a wrongly-set AgentType. Skipping here would
41	//     lock in a bad state.
42	func eventBypassesAgentOwnershipCheck(t agent.EventType) bool {
43		return t == agent.SessionStart || t == agent.TurnStart
44	}
45	
46	// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
47	// Returns nil if the event was handled successfully.
48	func DispatchLifecycleEvent(ctx context.Context, ag agent.Agent, event *agent.Event) error {
49		if ag == nil {
50			return errors.New("agent cannot be nil")
51		}
52		if event == nil {
53			return errors.New("event cannot be nil")
54		}
55	
56		// Reject path-unsafe identifiers once, here, before any handler uses them to
57		// build filesystem paths. Handlers historically validated individually,
58		// which is fragile — handleLifecycleTurnEnd builds .entire/metadata/<id>/
59		// via os.MkdirAll + os.WriteFile, and handleLifecycleSubagentEnd builds a
60		// subagent transcript path from SubagentID and reads it, without their own
61		// checks. Centralizing the guard covers every handler (and any future one)
62		// uniformly. Empty IDs pass through: handlers apply their own empty-handling
63		// (e.g. TurnEnd falls back to a safe constant; SubagentEnd skips the path).
64		if event.SessionID != "" {
65			if err := validation.ValidateSessionID(event.SessionID); err != nil {
66				return fmt.Errorf("invalid session ID in %s event: %w", event.Type, err)
67			}
68		}
69		if event.ToolUseID != "" {
70			if err := validation.ValidateToolUseID(event.ToolUseID); err != nil {
71				return fmt.Errorf("invalid tool use ID in %s event: %w", event.Type, err)
72			}
73		}
74		if event.SubagentID != "" {
75			if err := validation.ValidateAgentID(event.SubagentID); err != nil {
76				return fmt.Errorf("invalid subagent ID in %s event: %w", event.Type, err)
77			}
78		}
79	
80		// Filter forwarded hooks: when Cursor IDE forwards events to both
81		// .cursor/hooks.json and .claude/settings.json, only the agent that owns
82		// the session should process them — otherwise checkpoints, metadata
83		// writes, and step counts double.
84		if event.SessionID != "" && !eventBypassesAgentOwnershipCheck(event.Type) {
85			if state, _ := strategy.LoadSessionState(ctx, event.SessionID); state != nil && state.AgentType != "" && state.AgentType != ag.Type() { //nolint:errcheck // a load failure means we can't filter; let the event reach its handler, which surfaces its own load error
86				logging.Info(logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name()),
87					"skipping forwarded hook for non-owning agent",
88					slog.String("event", event.Type.String()),
89					slog.String("session_id", event.SessionID),
90					slog.String("owning_agent", string(state.AgentType)),
91					slog.String("firing_agent", string(ag.Type())),
92				)
93				return nil
94			}
95		}
96	
97		switch event.Type {
98		case agent.SessionStart:
99			return handleLifecycleSessionStart(ctx, ag, event)
100		case agent.TurnStart:
101			return handleLifecycleTurnStart(ctx, ag, event)
102		case agent.TurnEnd:
103			return handleLifecycleTurnEnd(ctx, ag, event)
104		case agent.Compaction:
105			return handleLifecycleCompaction(ctx, ag, event)
106		case agent.SessionEnd:
107			return handleLifecycleSessionEnd(ctx, ag, event)
108		case agent.SubagentStart:
109			return handleLifecycleSubagentStart(ctx, ag, event)
110		case agent.SubagentEnd:
111			return handleLifecycleSubagentEnd(ctx, ag, event)
112		case agent.ModelUpdate:
113			return handleLifecycleModelUpdate(ctx, ag, event)
114		case agent.ToolUse:
115			return handleLifecycleToolUse(ctx, ag, event)
116		default:
117			return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
118		}
119	}
120	
121	// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
122	// fires state machine transition.
123	func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
124		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
125		logging.Info(logCtx, "session-start",
126			slog.String("event", event.Type.String()),
127			slog.String("session_id", event.SessionID),
128			slog.String("session_ref", event.SessionRef),
129			slog.String("model", event.Model),
130		)
131	
132		if event.SessionID == "" {
133			return fmt.Errorf("no session_id in %s event", event.Type)
134		}
135		if err := validation.ValidateSessionID(event.SessionID); err != nil {
136			return fmt.Errorf("invalid %s event: %w", event.Type, err)
137		}
138	
139		// Claim the session for this agent. First-writer-wins: subsequent agents
140		// firing SessionStart for the same session ID are no-ops. Used by
141		// InitializeSession (TurnStart) and the dispatcher skip in
142		// DispatchLifecycleEvent for cross-agent disambiguation when Cursor IDE
143		// forwards hooks to both .cursor/hooks.json and .claude/settings.json.
144		if _, hintErr := strategy.StoreAgentTypeHint(ctx, event.SessionID, ag.Type()); hintErr != nil {
145			logging.Warn(logCtx, "failed to store agent hint on session start",
146				slog.String("error", hintErr.Error()))
147		}
148	
149		// Build informational message — warn early if repo has no commits yet,
150		// since checkpoints require at least one commit to work.
151		message := sessionStartMessage(ag.Name(), false)
152		if repo, err := strategy.OpenRepository(ctx); err == nil {
153			defer repo.Close()
154			if strategy.IsEmptyRepository(repo) {
155				message = sessionStartMessage(ag.Name(), true)
156			}
157		}
158	
159		// Check for concurrent sessions and append count if any
160		_, countSessionsSpan := perf.Start(ctx, "count_active_sessions")
161		strat := GetStrategy(ctx)
162		if count, err := strat.CountOtherActiveSessionsWithCheckpoints(ctx, event.SessionID); err == nil && count > 0 {
163			if ag.Name() == agent.AgentNameCodex {
164				message += fmt.Sprintf(" %d other active conversation(s) in this workspace will also be included. Use 'entire status' for more information.", count)
165			} else {
166				message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
167			}
168		}
169		countSessionsSpan.End()
170	
171		// Codex-only: surface untrusted hooks. Reaching this point means
172		// SessionStart is itself trusted, but a newer entire release may have
173		// added hooks (e.g. PostToolUse) that the user hasn't approved on
174		// this machine. Trust state is keyed by the absolute hooks.json
175		// path, so missing entries here flag exactly that case.
176		if ag.Name() == agent.AgentNameCodex {
177			if root, err := paths.WorktreeRoot(ctx); err == nil {
178				if gaps := codex.HookTrustGaps(root); len(gaps) > 0 {
179					message += fmt.Sprintf(" %d new hook(s) await approval (%s). Open /hooks to trust them.", len(gaps), strings.Join(gaps, ", "))
180				}
181			}
182		}
183	
184		// Output informational message if the agent supports hook responses.
185		// Claude Code reads JSON from stdout; agents that don't implement
186		// HookResponseWriter silently skip (avoids raw JSON in their terminal).
187		//
188		// Banner display is gated by ClaimSessionStartBanner — separate from the
189		// agent-ownership claim above. If the ownership winner can't write banners
190		// (Cursor), we'd suppress the banner entirely on a Cursor+Claude race;
191		// the banner marker is only claimed inside this branch so a non-writer
192		// winner can't consume the user's only banner.
193		_, hookResponseSpan := perf.Start(ctx, "write_hook_response")
194		if event.ResponseMessage != "" {
195			message = event.ResponseMessage
196		}
197		if writer, ok := agent.AsHookResponseWriter(ag); ok {
198			bannerFirst, bErr := strategy.ClaimSessionStartBanner(ctx, event.SessionID)
199			if bErr != nil {
200				// Better to duplicate the banner than to suppress the only one.
201				logging.Warn(logCtx, "failed to claim session start banner marker",
202					slog.String("error", bErr.Error()))
203				bannerFirst = true
204			}
205			if bannerFirst {
206				if err := writer.WriteHookResponse(message); err != nil {
207					hookResponseSpan.RecordError(err)
208					hookResponseSpan.End()
209					return fmt.Errorf("failed to write hook response: %w", err)
210				}
211			}
212		}
213		hookResponseSpan.End()
214	
215		// Store model hint if the agent provided model info on SessionStart
216		if event.Model != "" {
217			if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
218				logging.Warn(logCtx, "failed to store model hint on session start",
219					slog.String("error", err.Error()))
220			}
221		}
222	
223		// Fire EventSessionStart for the current session (if state exists).
224		// SessionStart can fire before InitializeSession creates the state file,
225		// so ErrStateNotFound is the normal first-session path — only warn on
226		// genuinely unexpected errors, matching the rest of this file.
227		mutErr := strategy.MutateSessionState(ctx, event.SessionID, func(state *strategy.SessionState) error {
228			persistEventMetadataToState(event, state)
229			if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
230				logging.Warn(logCtx, "session start transition failed",
231					slog.String("error", transErr.Error()))
232			}
233			return nil
234		})
235		if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
236			logging.Warn(logCtx, "failed to update session state on start",
237				slog.String("error", mutErr.Error()))
238		}
239	
240		return nil
241	}
242	
243	func sessionStartMessage(agentName types.AgentName, emptyRepo bool) string {
244		if agentName == agent.AgentNameCodex {
245			if emptyRepo {
246				return "Entire CLI found no commits yet — checkpoints will activate after your first commit."
247			}
248			return "Entire CLI will link this conversation to your next commit."
249		}
250	
251		if emptyRepo {
252			return "\n\nEntire CLI found no commits yet — checkpoints will activate after your first commit."
253		}
254		return "\n\nEntire CLI will link this conversation to your next commit."
255	}
256	
257	// handleLifecycleModelUpdate persists the model name for the current session.
258	//
259	// If the session state file already exists (e.g., Gemini's BeforeModel fires
260	// after TurnStart), the model is written directly to state.ModelName — no hint
261	// file needed. Otherwise falls back to StoreModelHint for cross-process
262	// persistence (see its doc comment for the full rationale).
263	func handleLifecycleModelUpdate(ctx context.Context, ag agent.Agent, event *agent.Event) error {
264		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
265		logging.Info(logCtx, "model-update",
266			slog.String("session_id", event.SessionID),
267			slog.String("model", event.Model),
268		)
269	
270		if event.SessionID == "" || event.Model == "" {
271			return nil
272		}
273	
274		// Prefer writing directly to session state when it exists
275		mutErr := strategy.MutateSessionState(ctx, event.SessionID, func(state *strategy.SessionState) error {
276			state.ModelName = event.Model
277			return nil
278		})
279		if mutErr == nil {
280			return nil
281		}
282		if !errors.Is(mutErr, strategy.ErrStateNotFound) {
283			logging.Warn(logCtx, "failed to update session state with model",
284				slog.String("error", mutErr.Error()))
285			return nil
286		}
287	
288		// State doesn't exist yet — use hint file (see StoreModelHint doc)
289		if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
290			logging.Warn(logCtx, "failed to store model hint",
291				slog.String("error", err.Error()))
292		}
293	
294		return nil
295	}
296	
297	// handleLifecycleToolUse merges files reported by a per-tool-use hook into
298	// the session's FilesTouched. Lightweight by design: no SaveStep, no shadow
299	// branch commit — just enough so PostCommit's carry-forward decision sees
300	// an accurate file list mid-turn.
301	func handleLifecycleToolUse(ctx context.Context, ag agent.Agent, event *agent.Event) error {
302		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
303	
304		if event.SessionID == "" {
305			return nil
306		}
307		if err := validation.ValidateSessionID(event.SessionID); err != nil {
308			return fmt.Errorf("invalid %s event: %w", event.Type, err)
309		}
310	
311		repoRoot, err := paths.WorktreeRoot(ctx)
312		if err != nil {
313			// Outside a repo or repo missing — nothing to track. Don't fail the hook.
314			logging.Debug(logCtx, "tool-use: no worktree root, skipping",
315				slog.String("session_id", event.SessionID),
316				slog.String("error", err.Error()),
317			)
318			return nil
319		}
320	
321		modified := normalizeToolUsePaths(event.ModifiedFiles, event.CWD, repoRoot)
322		added := normalizeToolUsePaths(event.NewFiles, event.CWD, repoRoot)
323		deleted := normalizeToolUsePaths(event.DeletedFiles, event.CWD, repoRoot)
324	
325		if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
326			return nil
327		}
328	
329		logging.Debug(logCtx, "tool-use: recording files touched",
330			slog.String("session_id", event.SessionID),
331			slog.Int("modified", len(modified)),
332			slog.Int("added", len(added)),
333			slog.Int("deleted", len(deleted)),
334		)
335	
336		if err := strategy.RecordFilesTouched(ctx, event.SessionID, modified, added, deleted); err != nil {
337			logging.Warn(logCtx, "tool-use: failed to record files touched",
338				slog.String("session_id", event.SessionID),
339				slog.String("error", err.Error()),
340			)
341		}
342		return nil
343	}
344	
345	// normalizeToolUsePaths converts hook-payload paths to repo-root-relative form.
346	// Codex apply_patch envelopes carry cwd-relative paths, so we join them against
347	// eventCWD before FilterAndNormalizePaths rewrites against repoRoot.
348	func normalizeToolUsePaths(files []string, eventCWD, repoRoot string) []string {
349		if len(files) == 0 {
350			return nil
351		}
352		resolved := make([]string, 0, len(files))
353		for _, f := range files {
354			if f == "" {
355				continue
356			}
357			if filepath.IsAbs(f) || eventCWD == "" {
358				resolved = append(resolved, f)
359				continue
360			}
361			resolved = append(resolved, filepath.Join(eventCWD, f))
362		}
363		return FilterAndNormalizePaths(resolved, repoRoot)
364	}
