366	// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
367	// ensures strategy setup, initializes session.
368	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
369		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
370		logging.Info(logCtx, "turn-start",
371			slog.String("event", event.Type.String()),
372			slog.String("session_id", event.SessionID),
373			slog.String("session_ref", event.SessionRef),
374			slog.String("model", event.Model),
375		)
376	
377		sessionID := event.SessionID
378		if sessionID == "" {
379			return fmt.Errorf("no session_id in %s event", event.Type)
380		}
381		if err := validation.ValidateSessionID(sessionID); err != nil {
382			return fmt.Errorf("invalid %s event: %w", event.Type, err)
383		}
384	
385		// Fill model from hint file if the agent didn't provide it on this hook
386		if event.Model == "" {
387			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
388				event.Model = hint
389				logging.Debug(logCtx, "loaded model from hint file",
390					slog.String("model", hint))
391			}
392		}
393	
394		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
395		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
396		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
397			captureSpan.RecordError(err)
398			captureSpan.End()
399			return err
400		}
401		captureSpan.End()
402	
403		// Append prompt to prompt.txt on filesystem so it's available for
404		// mid-turn commits (before SaveStep writes it to the shadow branch).
405		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
406		if event.Prompt != "" {
407			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
408			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
409				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
410					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
411					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
412					var content string
413					if readErr == nil && len(existing) > 0 {
414						content = string(existing) + "\n\n---\n\n" + event.Prompt
415					} else {
416						content = event.Prompt
417					}
418					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
419						logging.Warn(logCtx, "failed to write prompt.txt",
420							slog.String("error", writeErr.Error()))
421					}
422				}
423			}
424		}
425	
426		// Ensure strategy setup and initialize session
427		_, initSpan := perf.Start(ctx, "init_session")
428		if err := strategy.EnsureSetup(ctx); err != nil {
429			logging.Warn(logCtx, "failed to ensure strategy setup",
430				slog.String("error", err.Error()))
431		}
432	
433		strat := GetStrategy(ctx)
434		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
435			logging.Warn(logCtx, "failed to initialize session state",
436				slog.String("error", err.Error()))
437		}
438	
439		// Best-effort: adopt ENTIRE_REVIEW_* / ENTIRE_INVESTIGATE_* env vars set
440		// by `entire review` / `entire investigate` on the spawned agent process.
441		// Each agent process has its own env, so there is no file race across
442		// worktrees. Errors in load/save must not fail the turn.
443		//
444		// Review adoption runs first; if both env families are somehow set, review
445		// wins. Production strips ENTIRE_REVIEW_* in AppendInvestigateEnv before
446		// spawning each per-turn investigate agent process so this conflict cannot
447		// happen for fresh investigate spawns. Both functions short-circuit on
448		// state.Kind != "" to keep the conflict harmless if it ever arises.
449		if mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
450			before := *state
451			// Slice fields share their backing array under struct copy. If
452			// adoptReviewEnv ever mutates ReviewSkills in place, the diff check
453			// below would silently miss it. Clone to keep the comparison honest.
454			before.ReviewSkills = slices.Clone(state.ReviewSkills)
455			adoptReviewEnv(logCtx, state, string(ag.Name()))
456			adoptInvestigateEnv(logCtx, state, string(ag.Name()))
457	
458			skillEventSource := *event
459			// Record a skill event for a leading "/<command>" in the raw prompt. Only
460			// once ownership is known — TurnStart bypasses the owner filter so
461			// InitializeSession can repair it — and never overriding native adapter events.
462			if state.AgentType == "" || state.AgentType == ag.Type() {
463				skillEventSource.SkillEvents = agent.AppendPromptSlashCommandSkillEvent(
464					skillEventSource.SkillEvents,
465					string(ag.Name()),
466					event.Prompt,
467					event.Timestamp,
468				)
469			}
470			skillEventsChanged := appendEventSkillEventsToState(&skillEventSource, state)
471			if state.Kind == before.Kind &&
472				state.ReviewPrompt == before.ReviewPrompt &&
473				slices.Equal(state.ReviewSkills, before.ReviewSkills) &&
474				state.InvestigateRunID == before.InvestigateRunID &&
475				state.InvestigateTopic == before.InvestigateTopic &&
476				!skillEventsChanged {
477				return strategy.ErrMutationSkip
478			}
479			return nil
480		}); mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
481			logging.Warn(logCtx, "failed to save session state after review/investigate env adoption",
482				slog.String("error", mutErr.Error()))
483		}
484		initSpan.End()
485	
486		return nil
487	}
488	
489	// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
490	// detects file changes, saves step + checkpoint, transitions phase.
491	//
492	//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
493	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
494		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
495		logging.Info(logCtx, "turn-end",
496			slog.String("event", event.Type.String()),
497			slog.String("session_id", event.SessionID),
498			slog.String("session_ref", event.SessionRef),
499			slog.String("model", event.Model),
500		)
501	
502		sessionID := event.SessionID
503		if sessionID == "" {
504			sessionID = unknownSessionID
505		}
506	
507		// Fill model from hint file if the agent didn't provide it on this hook
508		if event.Model == "" && sessionID != unknownSessionID {
509			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
510				event.Model = hint
511				logging.Debug(logCtx, "loaded model from hint file",
512					slog.String("model", hint))
513			}
514		}
515	
516		transcriptRef := event.SessionRef
517		if transcriptRef == "" {
518			return errors.New("transcript file not specified")
519		}
520	
521		// If agent implements TranscriptPreparer, materialize the transcript file.
522		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
523		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
524		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
525		// TranscriptPreparer (Gemini, Droid) are unaffected.
526		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
527		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
528			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
529				logging.Warn(logCtx, "failed to prepare transcript",
530					slog.String("error", err.Error()))
531			}
532		}
533	
534		if !fileExists(transcriptRef) {
535			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
536			prepareSpan.End()
537			return fmt.Errorf("transcript file not found: %s", transcriptRef)
538		}
539	
540		// Early check: bail out quickly if the repo has no commits yet.
541		// Return nil (not an error) so the hook exits 0 — agents treat non-zero
542		// exit codes as hook failures. The user was already warned at session start.
543		if repo, err := strategy.OpenRepository(ctx); err == nil {
544			defer repo.Close()
545			if strategy.IsEmptyRepository(repo) {
546				prepareSpan.End()
547				logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
548				return nil
549			}
550		}
551		prepareSpan.End()
552	
553		// Create session metadata directory
554		_, copySpan := perf.Start(ctx, "copy_transcript")
555		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
556		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
557		if err != nil {
558			sessionDirAbs = sessionDir
559		}
560		if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
561			copySpan.RecordError(err)
562			copySpan.End()
563			return fmt.Errorf("failed to create session directory: %w", err)
564		}
565	
566		// Copy transcript to session directory
567		transcriptData, err := ag.ReadTranscript(transcriptRef)
568		if err != nil {
569			copySpan.RecordError(err)
570			copySpan.End()
571			return fmt.Errorf("failed to read transcript: %w", err)
572		}
573		logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
574		if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
575			copySpan.RecordError(err)
576			copySpan.End()
577			return fmt.Errorf("failed to write transcript: %w", err)
578		}
579		logging.Debug(logCtx, "copied transcript",
580			slog.String("path", sessionDir+"/"+paths.TranscriptFileName))
581		copySpan.End()
582	
583		// Load pre-prompt state (captured on TurnStart)
584		_, extractSpan := perf.Start(ctx, "extract_metadata")
585		preState, err := LoadPrePromptState(ctx, sessionID)
586		if err != nil {
587			logging.Warn(logCtx, "failed to load pre-prompt state",
588				slog.String("error", err.Error()))
589		}
590	
591		// Determine transcript offset
592		transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)
593	
594		// Backfill prompt.txt from transcript when prompt data is missing.
595		// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
596		// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
597		// there genuinely were no prompts. We track whether backfill occurred so we can
598		// update session state after SaveStep (which may reinitialize state).
599		var backfilledPrompt string
600		promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
601		existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
602		if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
603			logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
604				slog.String("error", readPromptErr.Error()))
605		} else if len(existingPrompt) == 0 {
606			if extractor, ok := agent.AsPromptExtractor(ag); ok {
607				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
608				if extractErr != nil {
609					logging.Warn(logCtx, "failed to extract prompts from transcript",
610						slog.String("error", extractErr.Error()))
611				} else if len(prompts) > 0 {
612					content := strings.Join(prompts, "\n\n---\n\n")
613					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
614						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
615							slog.String("error", writeErr.Error()))
616					} else {
617						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
618							slog.Int("prompt_count", len(prompts)))
619						backfilledPrompt = prompts[len(prompts)-1]
620					}
621				}
622			}
623		}
624	
625		// Compute subagents directory for agents that support subagent extraction.
626		// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
627		subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
628	
629		// Extract metadata via agent interface (modified files)
630		var modifiedFiles []string
631	
632		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
633			// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
634			if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
635				if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
636					logging.Warn(logCtx, "failed to extract modified files (with subagents)",
637						slog.String("error", fileErr.Error()))
638				} else {
639					modifiedFiles = files
640				}
641			} else {
642				// Fall back to basic extraction (main transcript only)
643				if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
644					logging.Warn(logCtx, "failed to extract modified files",
645						slog.String("error", fileErr.Error()))
646				} else {
647					modifiedFiles = files
648				}
649			}
650		}
651		extractSpan.End()
652	
653		// Generate commit message from last prompt (read from session state, set at TurnStart).
654		// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
655		// Fall back to backfilledPrompt extracted from the transcript.
656		// Single load serves both prompt retrieval and backfill.
657		_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
658		lastPrompt := ""
659		if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
660			lastPrompt = sessionState.LastPrompt
661		}
662		// Backfill LastPrompt so `entire status` shows the prompt even when no
663		// files were modified (before the early return below).
664		if lastPrompt == "" && backfilledPrompt != "" {
665			lastPrompt = backfilledPrompt
666			mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
667				if state.LastPrompt != "" {
668					return strategy.ErrMutationSkip
669				}
670				state.LastPrompt = backfilledPrompt
671				return nil
672			})
673			if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
674				logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
675					slog.String("error", mutErr.Error()))
676			}
677		}
678		commitMessage := generateCommitMessage(lastPrompt, ag.Type())
679		logging.Debug(logCtx, "using commit message",
680			slog.Int("message_length", len(commitMessage)))
681		commitMsgSpan.End()
682	
683		// Get worktree root for path normalization
684		_, detectSpan := perf.Start(ctx, "detect_file_changes")
685		repoRoot, err := paths.WorktreeRoot(ctx)
686		if err != nil {
687			detectSpan.RecordError(err)
688			detectSpan.End()
689			return fmt.Errorf("failed to get worktree root: %w", err)
690		}
691	
692		var preUntrackedFiles []string
693		if preState != nil {
694			logging.Debug(logCtx, "pre-prompt state",
695				slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
696			preUntrackedFiles = preState.PreUntrackedFiles()
697		}
698	
699		// Detect file changes via git status
700		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
701		if err != nil {
702			logging.Warn(logCtx, "failed to compute file changes",
703				slog.String("error", err.Error()))
704		}
705		detectSpan.End()
706	
707		// Filter and normalize all paths
708		_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
709		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
710		var relNewFiles, relDeletedFiles []string
711		if changes != nil {
712			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
713			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
714	
715			// Merge git-status modified files as a fallback for transcript parsing.
716			// Transcript parsing is the primary source for modified files, but it can miss
717			// files if the agent uses an unrecognized tool or the transcript format changes.
718			// Git status catches any tracked file with working-tree changes.
719			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
720		}
721	
722		// Filter transcript-extracted files to exclude files already committed to HEAD.
723		// When an agent commits files mid-turn, those files are condensed by PostCommit
724		// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
725		// if it exists in HEAD with the same content as the working tree.
726		relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
727		normalizeSpan.End()
728	
729		// Check if there are any changes
730		totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
731		if totalChanges == 0 {
732			logging.Info(logCtx, "no files modified during session, skipping checkpoint")
733			transitionSessionTurnEnd(ctx, sessionID, event)
734			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
735				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
736					slog.String("error", cleanupErr.Error()))
737			}
738			return nil
739		}
740	
741		// Log file changes
742		logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)
743	
744		// Get git author
745		author, err := GetGitAuthor(ctx)
746		if err != nil {
747			return fmt.Errorf("failed to get git author: %w", err)
748		}
749	
750		// Get strategy and agent type
751		strat := GetStrategy(ctx)
752		agentType := ag.Type()
753	
754		// Get transcript position/identifier from pre-prompt state
755		var transcriptIdentifierAtStart string
756		var transcriptLinesAtStart int
757		if preState != nil {
758			transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
759			transcriptLinesAtStart = preState.TranscriptOffset
760		}
761	
762		// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
763		tokenUsage := agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
764	
765		// Build fully-populated step context and delegate to strategy
766		stepCtx := strategy.StepContext{
767			SessionID:                sessionID,
768			ModifiedFiles:            relModifiedFiles,
769			NewFiles:                 relNewFiles,
770			DeletedFiles:             relDeletedFiles,
771			MetadataDir:              sessionDir,
772			MetadataDirAbs:           sessionDirAbs,
773			CommitMessage:            commitMessage,
774			TranscriptPath:           transcriptRef,
775			AuthorName:               author.Name,
776			AuthorEmail:              author.Email,
777			AgentType:                agentType,
778			StepTranscriptIdentifier: transcriptIdentifierAtStart,
779			StepTranscriptStart:      transcriptLinesAtStart,
780			TokenUsage:               tokenUsage,
781		}
782	
783		if err := strat.SaveStep(ctx, stepCtx); err != nil {
784			return fmt.Errorf("failed to save step: %w", err)
785		}
786	
787		// Update session state with backfilled prompt after SaveStep.
788		// Done after SaveStep because SaveStep may reinitialize session state,
789		// which would overwrite an earlier LastPrompt update.
790		if backfilledPrompt != "" {
791			mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
792				if state.LastPrompt != "" {
793					return strategy.ErrMutationSkip
794				}
795				state.LastPrompt = backfilledPrompt
796				return nil
797			})
798			if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
799				logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
800					slog.String("error", mutErr.Error()))
801			}
802		}
803	
804		// Transition session phase and cleanup
805		transitionSessionTurnEnd(ctx, sessionID, event)
806		if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
807			logging.Warn(logCtx, "failed to cleanup pre-prompt state",
808				slog.String("error", cleanupErr.Error()))
809		}
810	
811		return nil
812	}
