814	// handleLifecycleCompaction handles context compaction: saves current progress
815	// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
816	// Also resets the transcript offset since the transcript may be truncated.
817	func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
818		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
819		logging.Info(logCtx, "compaction",
820			slog.String("event", event.Type.String()),
821			slog.String("session_id", event.SessionID),
822		)
823	
824		// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
825		mutErr := strategy.MutateSessionState(ctx, event.SessionID, func(state *strategy.SessionState) error {
826			persistEventMetadataToState(event, state)
827			if transErr := strategy.TransitionAndLog(ctx, state, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
828				logging.Warn(logCtx, "compaction transition failed",
829					slog.String("error", transErr.Error()))
830			}
831			return nil
832		})
833		if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
834			logging.Warn(logCtx, "failed to save session state after compaction",
835				slog.String("error", mutErr.Error()))
836		}
837	
838		logging.Info(logCtx, "context compaction detected")
839		return nil
840	}
841	
842	// handleLifecycleSessionEnd handles session end: marks the session as ended.
843	func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
844		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
845		logging.Info(logCtx, "session-end",
846			slog.String("event", event.Type.String()),
847			slog.String("session_id", event.SessionID),
848		)
849	
850		if event.SessionID == "" {
851			return nil // No session to update
852		}
853	
854		// Note: We intentionally don't clean up cached transcripts here.
855		// Post-session commits (carry-forward in ENDED phase) may still need
856		// the transcript to extract file changes. Cleanup is handled by
857		// `entire clean` or when the session state is fully removed.
858	
859		if err := markSessionEnded(ctx, event, event.SessionID); err != nil {
860			logging.Warn(logCtx, "failed to mark session ended",
861				slog.String("error", err.Error()))
862			// Don't attempt eager condense if we couldn't even mark the session ended —
863			// the session state may be in an inconsistent state.
864			return nil
865		}
866	
867		// Eagerly condense session data so PostCommit doesn't have to process it.
868		// This prevents zombie ENDED sessions from accumulating and causing O(N)
869		// overhead on every future commit (GitHub issue #591).
870		// Fail-open: if this fails, PostCommit will still process it on the next commit.
871		strat := GetStrategy(ctx)
872		if err := strat.CondenseAndMarkFullyCondensed(ctx, event.SessionID); err != nil {
873			logging.Warn(logCtx, "eager condense on session stop failed",
874				slog.String("session_id", event.SessionID),
875				slog.String("error", err.Error()))
876		}
877	
878		return nil
879	}
880	
881	// handleLifecycleSubagentStart handles subagent start: captures pre-task state.
882	func handleLifecycleSubagentStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
883		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
884		logging.Info(logCtx, "subagent started",
885			slog.String("event", event.Type.String()),
886			slog.String("session_id", event.SessionID),
887			slog.String("tool_use_id", event.ToolUseID),
888			slog.String("transcript", event.SessionRef),
889		)
890	
891		// Capture pre-task state
892		if err := CapturePreTaskState(ctx, event.ToolUseID); err != nil {
893			return fmt.Errorf("failed to capture pre-task state: %w", err)
894		}
895	
896		return nil
897	}
