899	// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
900	func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
901		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
902		if event.SubagentType == "" && event.TaskDescription == "" {
903			// Extract subagent type and description from tool input
904			event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
905		}
906	
907		// Determine subagent transcript path
908		transcriptDir := filepath.Dir(event.SessionRef)
909		var subagentTranscriptPath string
910		if event.SubagentID != "" {
911			subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
912			if !fileExists(subagentTranscriptPath) {
913				subagentTranscriptPath = ""
914			}
915		}
916	
917		// Log context
918		subagentEndAttrs := []any{
919			slog.String("event", event.Type.String()),
920			slog.String("session_id", event.SessionID),
921			slog.String("tool_use_id", event.ToolUseID),
922		}
923		if event.SubagentID != "" {
924			subagentEndAttrs = append(subagentEndAttrs, slog.String("agent_id", event.SubagentID))
925		}
926		if subagentTranscriptPath != "" {
927			subagentEndAttrs = append(subagentEndAttrs, slog.String("subagent_transcript", subagentTranscriptPath))
928		}
929		logging.Info(logCtx, "subagent completed", subagentEndAttrs...)
930	
931		// Extract modified files from hook payload and/or subagent transcript
932		var modifiedFiles []string
933		modifiedFiles = append(modifiedFiles, event.ModifiedFiles...)
934		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
935			transcriptToScan := event.SessionRef
936			if subagentTranscriptPath != "" {
937				transcriptToScan = subagentTranscriptPath
938			}
939			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
940				logging.Warn(logCtx, "failed to extract modified files from subagent",
941					slog.String("error", fileErr.Error()))
942			} else {
943				modifiedFiles = mergeUnique(modifiedFiles, files)
944			}
945		}
946	
947		// Load pre-task state and detect file changes.
948		// If no pre-task state exists (agent doesn't support pre-task hook), fall back
949		// to the session's pre-prompt state. Without either, DetectFileChanges receives
950		// nil and treats ALL untracked files as new — which would create spurious task
951		// checkpoints for pre-existing untracked files (e.g., .github/hooks/entire.json).
952		preState, err := LoadPreTaskState(ctx, event.ToolUseID)
953		if err != nil {
954			logging.Warn(logCtx, "failed to load pre-task state",
955				slog.String("error", err.Error()))
956		}
957		var preUntrackedFiles []string
958		if preState != nil {
959			preUntrackedFiles = preState.PreUntrackedFiles()
960		}
961		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
962		if err != nil {
963			logging.Warn(logCtx, "failed to compute file changes",
964				slog.String("error", err.Error()))
965		}
966	
967		// Get worktree root and normalize paths
968		repoRoot, err := paths.WorktreeRoot(ctx)
969		if err != nil {
970			return fmt.Errorf("failed to get worktree root: %w", err)
971		}
972	
973		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
974		var relNewFiles, relDeletedFiles []string
975		if changes != nil {
976			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
977			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
978			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
979		}
980	
981		// If no changes, skip
982		if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
983			logging.Info(logCtx, "no file changes detected, skipping task checkpoint")
984			_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
985			return nil
986		}
987	
988		// Find checkpoint UUID from main transcript (best-effort)
989		var checkpointUUID string
990		// Use the existing CLI-level checkpoint UUID finder
991		mainLines, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
992		if mainLines != nil {
993			checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
994		}
995	
996		// Get git author
997		author, err := GetGitAuthor(ctx)
998		if err != nil {
999			return fmt.Errorf("failed to get git author: %w", err)
1000		}
1001	
1002		// Build task checkpoint context
1003		strat := GetStrategy(ctx)
1004		agentType := ag.Type()
1005	
1006		taskStepCtx := strategy.TaskStepContext{
1007			SessionID:              event.SessionID,
1008			ToolUseID:              event.ToolUseID,
1009			AgentID:                event.SubagentID,
1010			ModifiedFiles:          relModifiedFiles,
1011			NewFiles:               relNewFiles,
1012			DeletedFiles:           relDeletedFiles,
1013			TranscriptPath:         event.SessionRef,
1014			SubagentTranscriptPath: subagentTranscriptPath,
1015			CheckpointUUID:         checkpointUUID,
1016			AuthorName:             author.Name,
1017			AuthorEmail:            author.Email,
1018			SubagentType:           event.SubagentType,
1019			TaskDescription:        event.TaskDescription,
1020			AgentType:              agentType,
1021		}
1022	
1023		if err := strat.SaveTaskStep(ctx, taskStepCtx); err != nil {
1024			return fmt.Errorf("failed to save task step: %w", err)
1025		}
1026	
1027		_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
1028		return nil
1029	}
1030	
1031	// --- Helper functions ---
1032	
1033	// resolveTranscriptOffset determines the transcript offset to use for parsing.
1034	// Prefers pre-prompt state, falls back to session state.
1035	func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
1036		logCtx := logging.WithComponent(ctx, "lifecycle")
1037		if preState != nil && preState.TranscriptOffset > 0 {
1038			logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
1039				slog.Int("offset", preState.TranscriptOffset))
1040			return preState.TranscriptOffset
1041		}
1042	
1043		// Fall back to session state
1044		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
1045		if loadErr != nil {
1046			logging.Warn(logCtx, "failed to load session state",
1047				slog.String("error", loadErr.Error()))
1048			return 0
1049		}
1050		if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
1051			logging.Debug(logCtx, "session state found, parsing transcript from offset",
1052				slog.Int("offset", sessionState.CheckpointTranscriptStart))
1053			return sessionState.CheckpointTranscriptStart
1054		}
1055	
1056		return 0
1057	}
1058	
1059	// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
1060	// Returns parsed transcript lines for use with FindCheckpointUUID.
1061	func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, error) {
1062		lines, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
1063		if err != nil {
1064			return nil, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
1065		}
1066		return lines, nil
1067	}
1068	
1069	// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
1070	func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
1071		logCtx := logging.WithComponent(ctx, "lifecycle")
1072		mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
1073			persistEventMetadataToState(event, state)
1074			if err := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
1075				logging.Warn(logCtx, "turn-end transition failed",
1076					slog.String("error", err.Error()))
1077			}
1078			// HandleTurnEnd mutates state in-place; the outer MutateSessionState
1079			// save flushes those changes. Any reentrant MutateSessionState calls
1080			// it makes on this session ID share this state pointer via the gate.
1081			strat := GetStrategy(ctx)
1082			if err := strat.HandleTurnEnd(ctx, state); err != nil {
1083				logging.Warn(logCtx, "turn-end action dispatch failed",
1084					slog.String("error", err.Error()))
1085			}
1086			return nil
1087		})
1088		if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
1089			logging.Warn(logCtx, "failed to update session phase on turn end",
1090				slog.String("error", mutErr.Error()))
1091		}
1092	}
1093	
1094	// markSessionEnded transitions the session to ENDED phase via the state machine.
1095	// If event is non-nil, hook-provided metrics are persisted to state before saving.
1096	func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string) error {
1097		mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
1098			if event != nil {
1099				persistEventMetadataToState(event, state)
1100			}
1101			if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
1102				logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
1103					slog.String("error", transErr.Error()))
1104			}
1105			now := time.Now()
1106			state.EndedAt = &now
1107			return nil
1108		})
1109		if errors.Is(mutErr, strategy.ErrStateNotFound) {
1110			return nil
1111		}
1112		if mutErr != nil {
1113			return fmt.Errorf("failed to save session state: %w", mutErr)
1114		}
1115		return nil
1116	}
1117	
1118	// logFileChanges logs the files modified, created, and deleted during a session.
1119	func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
1120		logCtx := logging.WithComponent(ctx, "lifecycle")
1121		logging.Debug(logCtx, "files changed during session",
1122			slog.Int("modified", len(modified)),
1123			slog.Int("new", len(newFiles)),
1124			slog.Int("deleted", len(deleted)))
1125	}
1126	
1127	func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
1128		// Update ModelName if provided (model is known by turn-end even on first turn)
1129		if event.Model != "" {
1130			state.ModelName = event.Model
1131		}
1132		appendEventSkillEventsToState(event, state)
1133	
1134		// Persist hook-provided session metrics (e.g., from Cursor hooks)
1135		if event.DurationMs > 0 {
1136			state.SessionDurationMs = event.DurationMs
1137		}
1138		// Use hook-reported turn count if available (take max); otherwise
1139		// increment on each TurnEnd event to count turns ourselves.
1140		prevTurnCount := state.SessionTurnCount
1141		if event.TurnCount > 0 {
1142			if event.TurnCount > state.SessionTurnCount {
1143				state.SessionTurnCount = event.TurnCount
1144			}
1145		} else if event.Type == agent.TurnEnd {
1146			state.SessionTurnCount++
1147		}
1148		// Deferred checkpoint-window reset: the first time the turn count actually
1149		// advances after a checkpoint was written, re-anchor the window base to the
1150		// count from before this turn so the current turn becomes the first prompt of
1151		// the new window. Gate on a real advance (not just a TurnEnd / non-zero
1152		// TurnCount) so a repeated or stale hook reporting the same cumulative count
1153		// doesn't re-anchor early — that would make a later back-to-back checkpoint
1154		// report 1 instead of matching the prior count.
1155		if state.SessionTurnCount > prevTurnCount && state.PromptWindowResetPending {
1156			state.PromptWindowBase = prevTurnCount
1157			state.PromptWindowResetPending = false
1158		}
1159		if event.ContextTokens > 0 {
1160			state.ContextTokens = event.ContextTokens
1161		}
1162		if event.ContextWindowSize > 0 {
1163			state.ContextWindowSize = event.ContextWindowSize
1164		}
1165	}
1166	
1167	func appendEventSkillEventsToState(event *agent.Event, state *strategy.SessionState) bool {
1168		if event == nil || state == nil || len(event.SkillEvents) == 0 {
1169			return false
1170		}
1171		changed := false
1172		for _, skillEvent := range event.SkillEvents {
1173			if skillEvent.TurnID == "" {
1174				skillEvent.TurnID = state.TurnID
1175			}
1176			if skillEventExists(state.SkillEvents, skillEvent) {
1177				continue
1178			}
1179			state.SkillEvents = append(state.SkillEvents, skillEvent)
1180			changed = true
1181		}
1182		return changed
1183	}
1184	
1185	func skillEventExists(events []agent.SkillEvent, candidate agent.SkillEvent) bool {
1186		for _, existing := range events {
1187			if existing.ID != "" && candidate.ID != "" {
1188				if existing.ID == candidate.ID {
1189					return true
1190				}
1191				continue
1192			}
1193			if existing.EventType == candidate.EventType &&
1194				existing.Skill.Name == candidate.Skill.Name &&
1195				existing.Source.Agent == candidate.Source.Agent &&
1196				existing.Source.Signal == candidate.Source.Signal &&
1197				existing.TurnID == candidate.TurnID {
1198				return true
1199			}
1200		}
1201		return false
1202	}
1203	
1204	// envAdoptionSpec carries the kind-specific bits of env-driven session
1205	// tagging. The shared scaffolding (idempotence guard, SESSION/AGENT/
1206	// STARTING_SHA gates) lives in tryAdoptEnv; apply runs only after the gates
1207	// pass and is responsible for decoding the kind-specific payload, mutating
1208	// state.Kind and the related fields, and emitting the success log.
1209	type envAdoptionSpec struct {
1210		kindLabel      string // "review" or "investigate" — log prefix
1211		envSession     string
1212		envAgent       string
1213		envStartingSHA string
1214		apply          func(ctx context.Context, state *session.State, expectedAgent string)
1215	}
1216	
1217	// tryAdoptEnv runs the shared env-adoption protocol for a launched-agent
1218	// process and delegates kind-specific decode/apply to spec.apply.
1219	//
1220	// The protocol:
1221	//  1. If state.Kind is already set, do nothing — adoption is idempotent
1222	//     across turns, and a session is review OR investigate, not both.
1223	//  2. envSession must be "1". `entire review` / `entire investigate` set
1224	//     this on the spawned agent process; the lifecycle hook (a child of
1225	//     the agent) inherits it naturally.
1226	//  3. envAgent must match the hook's agent — protects against stale env
1227	//     vars inherited from a parent shell or a nested invocation.
1228	//  4. envStartingSHA must match the session's BaseCommit — protects
1229	//     against env vars surviving a commit boundary.
1230	//
1231	// All failures log at debug/warn and leave state untagged.
1232	//
1233	// Trust model: this gate (env-present + agent-match + SHA-match) treats
1234	// the parent process environment as trusted. The CLI never exports these
1235	// vars to a user shell — they exist only on the in-process env of agents
1236	// spawned by `entire review` / `entire investigate` themselves, plus the
1237	// lifecycle hook (a child of that agent) which inherits them naturally.
1238	// A user who manually `export`s ENTIRE_REVIEW_AGENT=<their-agent> and
1239	// ENTIRE_REVIEW_STARTING_SHA=<HEAD-sha> before launching an agent COULD
1240	// forge a review-tagged session; that is considered out-of-scope for the
1241	// adoption guard. The SHA gate also self-invalidates on the next commit
1242	// (BaseCommit changes), so a stale-env forgery cannot persist across a
1243	// commit boundary even if it succeeded once.
1244	func tryAdoptEnv(ctx context.Context, state *session.State, expectedAgent string, spec envAdoptionSpec) {
1245		if state.Kind != "" {
1246			return
1247		}
1248		if envSession := os.Getenv(spec.envSession); envSession != "1" {
1249			logging.Debug(ctx, spec.kindLabel+" env adoption skipped: "+spec.envSession+" is not \"1\"",
1250				slog.String("expected_agent", expectedAgent),
1251				slog.String("observed_value", envSession))
1252			return
1253		}
1254		envAgent := os.Getenv(spec.envAgent)
1255		if envAgent != expectedAgent {
1256			logging.Warn(ctx, spec.kindLabel+" env adoption skipped: agent mismatch",
1257				slog.String("env_agent", envAgent),
1258				slog.String("hook_agent", expectedAgent))
1259			return
1260		}
1261		startingSHA := os.Getenv(spec.envStartingSHA)
1262		if startingSHA == "" || state.BaseCommit == "" || startingSHA != state.BaseCommit {
1263			logging.Warn(ctx, spec.kindLabel+" env adoption skipped: starting SHA mismatch",
1264				slog.String("env_starting_sha", startingSHA),
1265				slog.String("state_base_commit", state.BaseCommit))
1266			return
1267		}
1268		spec.apply(ctx, state, envAgent)
1269	}
1270	
1271	// adoptReviewEnv tags the session as a review session when ENTIRE_REVIEW_*
1272	// env vars are present on the current process.
1273	func adoptReviewEnv(ctx context.Context, state *session.State, expectedAgent string) {
1274		tryAdoptEnv(ctx, state, expectedAgent, envAdoptionSpec{
1275			kindLabel:      "review",
1276			envSession:     review.EnvSession,
1277			envAgent:       review.EnvAgent,
1278			envStartingSHA: review.EnvStartingSHA,
1279			apply: func(ctx context.Context, state *session.State, envAgent string) {
1280				skills, err := review.DecodeSkills(os.Getenv(review.EnvSkills))
1281				if err != nil {
1282					logging.Warn(ctx, "review env adoption failed: invalid skills JSON",
1283						slog.String("err", err.Error()))
1284					return
1285				}
1286				state.Kind = session.KindAgentReview
1287				state.ReviewSkills = skills
1288				state.ReviewPrompt = os.Getenv(review.EnvPrompt)
1289				logging.Debug(ctx, "adopted review env",
1290					slog.String("agent", envAgent),
1291					slog.Int("skill_count", len(skills)))
1292			},
1293		})
1294	}
1295	
1296	// adoptInvestigateEnv tags the session as an investigation session when
1297	// ENTIRE_INVESTIGATE_* env vars are present on the current process.
1298	//
1299	// Adoption ordering: adoptReviewEnv runs first; if both env families are
1300	// somehow set on the same process, review wins. Production strips
1301	// ENTIRE_REVIEW_* in AppendInvestigateEnv before spawning each per-turn
1302	// agent process, so this conflict cannot happen for fresh investigate spawns
1303	// — but tryAdoptEnv's short-circuit on state.Kind != "" makes the conflict
1304	// harmless if it ever arises.
1305	func adoptInvestigateEnv(ctx context.Context, state *session.State, expectedAgent string) {
1306		tryAdoptEnv(ctx, state, expectedAgent, envAdoptionSpec{
1307			kindLabel:      "investigate",
1308			envSession:     provenance.InvestigateSession,
1309			envAgent:       provenance.InvestigateAgent,
1310			envStartingSHA: provenance.InvestigateStartingSHA,
1311			apply: func(ctx context.Context, state *session.State, envAgent string) {
1312				runID := os.Getenv(provenance.InvestigateRunID)
1313				// Reject empty or malformed RunID — downstream condensation joins
1314				// session metadata by run ID, and tagging a session with no/invalid
1315				// ID would leak into checkpoint metadata as junk data.
1316				if !provenance.IsValidRunID(runID) {
1317					logging.Warn(ctx, "investigate env adoption skipped: invalid run id",
1318						slog.String("env_run_id", runID))
1319					return
1320				}
1321				state.Kind = session.KindAgentInvestigate
1322				state.InvestigateRunID = runID
1323				state.InvestigateTopic = os.Getenv(provenance.InvestigateTopic)
1324				logging.Debug(ctx, "adopted investigate env",
1325					slog.String("agent", envAgent),
1326					slog.String("run_id", state.InvestigateRunID))
1327			},
1328		})
1329	}
